1	package warranty
2	
3	import (
4		"fmt"
5		"sort"
6		"time"
7	)
8	
9	// CommitmentDetail 是承诺的明细视图，已取消或已到期的记录仍可追查。
10	type CommitmentDetail struct {
11		// CommitmentID 是承诺编号。
12		CommitmentID string
13		// RequestID 是关联请求编号。
14		RequestID string
15		// PartID 是备件编号。
16		PartID string
17		// OriginalQuantity 是原定承诺数量。
18		OriginalQuantity int
19		// UsedQuantity 是已用数量。
20		UsedQuantity int
21		// RemainingQuantity 是剩余未用数量。
22		RemainingQuantity int
23		// Expiry 是到期时刻。
24		Expiry time.Time
25		// Status 是在查询时刻的状态（active/canceled/expired）。
26		Status CommitmentStatus
27	}
28	
29	// PartStatus 是按备件查询的库存与占用视图。
30	type PartStatus struct {
31		// PartID 是备件编号。
32		PartID string
33		// PhysicalRemaining 是剩余实物库存（初始库存扣除全部成功使用量）。
34		PhysicalRemaining int
35		// ActiveOccupied 是有效承诺的未用总量。
36		ActiveOccupied int
37		// Committable 是还可承诺数量，等于剩余实物库存扣除有效承诺未用总量。
38		Committable int
39		// Details 是该备件的全部承诺明细（含已取消、已到期），按承诺编号排序。
40		Details []CommitmentDetail
41	}
42	
43	// RequestView 是按请求查询的资格与承诺视图。
44	type RequestView struct {
45		// Eligibility 是资格依据与拒绝原因。
46		Eligibility *Eligibility
47		// Commitments 是该请求关联的全部承诺明细（含已取消、已到期），按承诺编号排序。
48		Commitments []CommitmentDetail
49	}
50	
51	// toDetailLocked 生成承诺在指定时刻的明细。
52	func toDetailLocked(c *Commitment, now time.Time) CommitmentDetail {
53		return CommitmentDetail{
54			CommitmentID:      c.ID,
55			RequestID:         c.RequestID,
56			PartID:            c.PartID,
57			OriginalQuantity:  c.Quantity,
58			UsedQuantity:      c.Used,
59			RemainingQuantity: c.Quantity - c.Used,
60			Expiry:            c.Expiry,
61			Status:            c.Status(now),
62		}
63	}
64	
65	// RequestView 返回指定请求在当前时刻的资格依据、拒绝原因和关联承诺。
66	func (s *Store) RequestView(requestID string, now time.Time) (*RequestView, error) {
67		if requestID == "" {
68			return nil, fmt.Errorf("%w: request id must not be empty", ErrInvalidParam)
69		}
70		s.mu.Lock()
71		defer s.mu.Unlock()
72	
73		req, ok := s.requests[requestID]
74		if !ok {
75			return nil, fmt.Errorf("%w: request %q", ErrNotFound, requestID)
76		}
77		elig, err := s.evaluateLocked(req, now)
78		if err != nil {
79			return nil, err
80		}
81		view := &RequestView{Eligibility: elig}
82		for _, c := range s.commitments {
83			if c.RequestID != requestID {
84				continue
85			}
86			view.Commitments = append(view.Commitments, toDetailLocked(c, now))
87		}
88		sort.Slice(view.Commitments, func(i, j int) bool {
89			return view.Commitments[i].CommitmentID < view.Commitments[j].CommitmentID
90		})
91		return view, nil
92	}
93	
94	// PartStatus 返回指定备件在当前时刻的实物剩余、有效占用、可承诺数量和占用明细。
95	func (s *Store) PartStatus(partID string, now time.Time) (*PartStatus, error) {
96		if partID == "" {
97			return nil, fmt.Errorf("%w: part id must not be empty", ErrInvalidParam)
98		}
99		s.mu.Lock()
100		defer s.mu.Unlock()
101	
102		part, ok := s.parts[partID]
103		if !ok {
104			return nil, fmt.Errorf("%w: part %q", ErrNotFound, partID)
105		}
106		view := &PartStatus{PartID: partID, PhysicalRemaining: part.Stock}
107		for _, c := range s.commitments {
108			if c.PartID != partID {
109				continue
110			}
111			view.Details = append(view.Details, toDetailLocked(c, now))
